 if(path[0]==="material"&&path[1]==="group"&&path[2]==="info"&&path.length===4&&id.safeParse(path[3]).success){const group=await owned(db,"pub2_collections",user,path[3]);const metas=await all(db,"pub_native_collection_meta",user),meta=metas.find(item=>item.collection_id===group.id);if(method==="GET")return {data:{id:group.id,name:group.name,desc:group.description,type:"video",nativeRevision:group.revision,nativeMetadataRevision:meta?.revision??0}};if(method==="POST"){const input=z.object({name:z.string().trim().min(1).max(200),expectedRevision:revision,expectedMetadataRevision:z.number().int().nonnegative(),requestKey:coreRequestKey}).strict().safeParse(raw);if(!input.success)invalid();const result=await metadata(db,user,{action:"save-collection",base:{action:"save-collection",id:path[3],expectedRevision:input.data.expectedRevision,name:input.data.name,description:string(group.description),archived:Boolean(group.archived)},expectedMetadataRevision:input.data.expectedMetadataRevision,metadata:NativeCollectionMetadataSchema.parse(meta?.payload??{schemaVersion:1,platforms:[],useScene:null,useSceneRelId:null})},input.data.requestKey);return {data:{id:path[3],nativeRevision:object(object(result.base).row).revision,nativeMetadataRevision:result.metadataRevision}};}}
